//! TIDE Ocean Wave brand logo rendered in ANSI truecolor half-blocks.
//!
//! Provides large (42x21), medium (32x16), and compact (24x12) truecolor wave emblems.

use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span};

/// Default wave logo (large 42x21 hero emblem)
#[allow(dead_code)]
pub fn wave_halfblock_art() -> Vec<Line<'static>> {
    wave_large_halfblock_art()
}

/// Dynamically selects the best logo size to fit available viewport height
#[allow(dead_code)]
pub fn wave_art_for_height(available_height: u16) -> Vec<Line<'static>> {
    if available_height >= 26 {
        wave_large_halfblock_art()
    } else if available_height >= 18 {
        wave_medium_halfblock_art()
    } else {
        wave_compact_halfblock_art()
    }
}

